// Source-only owned fake backend. No actual command, module, proc/sys or signal effects.
mod platform; mod config; mod reboot; mod stop;
use platform::*;use std::{collections::BTreeMap,io};
#[derive(Default)]struct Fake{files:BTreeMap<String,String>,dirs:BTreeMap<String,Vec<String>>,calls:Vec<Call>,sleeps:Vec<u64>,messages:Vec<String>,fail:Option<(String,Vec<String>)>,destroy_failures:usize,mask:u32}
impl Fake{fn ready()->Self{let mut h=Self::default();h.files.insert("/proc/modules".into(),"ihk 1\nihk_smp_x86_64 1\nmcctrl 1\n".into());h.files.insert("/sbin/rmmod".into(),String::new());h}
 fn saw(&self,p:&str,args:&[&str])->bool{self.calls.iter().any(|c|c.program==p&&c.args==args)} }
impl Host for Fake{
 fn call(&mut self,c:Call)->Output{self.calls.push(c.clone());if self.fail.as_ref().map_or(false,|(p,a)|*p==c.program&&*a==c.args){return Output{code:1,..Output::default()}}
 if c.args.get(1).map(String::as_str)==Some("destroy")&&self.destroy_failures>0{self.destroy_failures-=1;return Output{code:1,..Output::default()}}
 let mut o=Output::default();match c.program.as_str(){"systemctl" if c.args.first().map(String::as_str)==Some("status")=>o.code=1,"pidof"|"getenforce"=>o.code=1,"id"=>o.out="tester\n".into(),"lscpu" if c.args==["--parse"]=>o.out="# CPU,Core,Socket,Node\n0,0,0,0\n1,1,0,0\n2,2,0,0\n3,3,0,0\n4,4,1,1\n".into(),"tee"=>{self.files.insert(c.args[0].clone(),c.input.unwrap_or_default());},_=>{if c.args==["0","get","buildid"]{o.out="fixture-build\n".into()}if c.args==["0","query","cpu"]{o.out="2-3\n".into()}}}o}
 fn read(&mut self,p:&str)->io::Result<String>{self.files.get(p).cloned().ok_or_else(||io::ErrorKind::NotFound.into())}
 fn list(&mut self,p:&str)->io::Result<Vec<String>>{Ok(self.dirs.get(p).cloned().unwrap_or_default())}
 fn exists(&mut self,p:&str)->bool{self.files.contains_key(p)||self.dirs.contains_key(p)}fn file(&mut self,p:&str)->bool{self.files.contains_key(p)}fn sleep(&mut self,ms:u64){self.sleeps.push(ms)}fn umask(&mut self,v:u32)->u32{let old=self.mask;self.mask=v;old}fn diagnostic(&mut self,s:&str){self.messages.push(s.into())}}
fn config()->config::Config{config::Config{sbin:"/owned/sbin".into(),etc:"/owned/etc".into(),modules:"/owned/modules".into(),kernel:"/owned/kernel".into(),arch:"x86_64".into(),buildid:"fixture-build".into(),linux_work_irq:false,trampoline:String::new()}}
fn args(s:&[&str])->Vec<String>{s.iter().map(|v|v.to_string()).collect()}
#[test]fn cli_options(){let o=reboot::parse(&args(&["-sthOR","-c2-3","-m","1G@0","-r","2-3:0","-q80","-T0","-e","foo bar","-fLOG_LOCAL4","-i2","-k1","-d7","-ouser"])).unwrap();assert!(o.safe&&o.turbo&&o.halt&&o.oversubscribe&&o.reserve);assert!(!o.sharing);assert_eq!(o.extra,"foo bar");assert_eq!(o.owner.as_deref(),Some("user"));assert!(reboot::parse(&args(&["-c"])).is_err());assert!(stop::parse(&args(&["-kR","extra"])).is_err());assert_eq!(stop::parse(&args(&["-kRr/owned/rmmod"])).unwrap(),stop::Options{rmmod:"/owned/rmmod".into(),kill:true,retain:true});}
#[test]fn cpu_masks_cross_word(){assert_eq!(reboot::masks("0,31-33",36).unwrap().1,"3,80000001");assert_eq!(reboot::masks("0,31-33",36).unwrap().2,"c,7ffffffe");assert!(reboot::masks("36",36).is_err());assert!(reboot::cpu_set("2-1").is_err());}
#[test]fn boot_existing_resources(){let mut h=Fake::ready();assert_eq!(reboot::execute(&mut h,&config(),&reboot::Options::default()),0);assert!(h.saw("/owned/sbin/ihkosctl",&["0","assign","cpu","2,3"]));assert!(h.saw("/owned/sbin/ihkosctl",&["0","load","/owned/kernel/mckernel.img"]));assert!(!h.calls.iter().any(|c|c.program=="insmod"||c.args.get(1).map(String::as_str)==Some("reserve")));assert_eq!(h.mask,0);}
#[test]fn boot_failure_keeps_preexisting_reservations(){let mut h=Fake::ready();h.fail=Some(("/owned/sbin/ihkosctl".into(),args(&["0","boot"])));assert_eq!(reboot::execute(&mut h,&config(),&reboot::Options::default()),1);assert!(h.saw("/owned/sbin/ihkconfig",&["0","destroy","0"]));assert!(!h.calls.iter().any(|c|c.program=="rmmod"||c.args.get(1).map(String::as_str)==Some("release")));}
#[test]fn boot_new_resources_reverse_rollback(){let mut h=Fake::ready();h.files.insert("/proc/modules".into(),String::new());h.fail=Some(("/owned/sbin/ihkosctl".into(),args(&["0","boot"])));let o=reboot::parse(&args(&["-c2-3","-R"])).unwrap();assert_eq!(reboot::execute(&mut h,&config(),&o),1);assert_eq!(h.calls.iter().filter(|c|c.args==["0","reserve","mem","512M@0"]).count(),1);assert!(h.saw("/owned/sbin/ihkconfig",&["0","release","cpu","2-3"]));assert!(h.saw("/owned/sbin/ihkconfig",&["0","release","mem","512M@0"]));let removals=h.calls.iter().filter(|c|c.program=="rmmod").map(|c|c.args[0].as_str()).collect::<Vec<_>>();assert_eq!(removals,["mcctrl","ihk_smp_x86_64","ihk"]);}
#[test]fn destroy_last_attempt_success(){let mut h=Fake::ready();h.destroy_failures=4;assert!(destroy(&mut h,"/owned/sbin/ihkconfig","0"));assert_eq!(h.sleeps,[250,250,250,250]);}
#[test]fn stop_retain_releases_without_unload(){let mut h=Fake::ready();let o=stop::parse(&args(&["-R"])).unwrap();assert_eq!(stop::execute(&mut h,&config(),&o),0);assert!(h.saw("/owned/sbin/ihkconfig",&["0","release","mem","all"]));assert!(!h.calls.iter().any(|c|c.program=="/sbin/rmmod"));assert_eq!(h.sleeps,[2000]);}
#[test]fn stop_failed_mem_does_not_unload(){let mut h=Fake::ready();h.fail=Some(("/owned/sbin/ihkconfig".into(),args(&["0","release","mem","all"])));assert_eq!(stop::execute(&mut h,&config(),&stop::parse(&[]).unwrap()),1);assert!(!h.calls.iter().any(|c|c.program=="/sbin/rmmod"));}
